/* Régression OLS : nuage de points déterministe + droite ajustée + β̂, R², t-stat */
(function () {
  var svg = document.getElementById("rg-chart");
  if (!svg) return;
  function v(id){ return parseFloat(document.getElementById(id).value); }
  function setT(id,t){ var e=document.getElementById(id); if(e) e.textContent=t; }
  function al(){ return document.body.getAttribute("data-active-lang")||"fr"; }

  // Générateur pseudo-aléatoire déterministe (LCG) + Box-Muller, seed fixe
  function makeNormals(count, seed){
    var out=[];
    function rnd(){ seed=(1103515245*seed+12345)&0x7fffffff; return seed/0x7fffffff; }
    for (var i=0;i<count;i++){
      var u1=Math.max(rnd(),1e-9), u2=rnd();
      out.push(Math.sqrt(-2*Math.log(u1))*Math.cos(2*Math.PI*u2));
    }
    return out;
  }
  var ZX = makeNormals(120, 987654321);   // écarts pour X
  var ZE = makeNormals(120, 246813579);   // chocs pour Y (séquence indépendante)
  var XMEAN=7.77, XSD=6.0, ALPHA=3.6;

  function draw(){
    var beta=v("rg-beta"), noise=v("rg-noise"), n=Math.round(v("rg-n"));
    setT("rg-beta-o", beta.toFixed(2)); setT("rg-noise-o", noise.toFixed(0)); setT("rg-n-o", n.toFixed(0));

    // Construire l'échantillon. On rend le choc orthogonal à X dans l'échantillon
    // (résidu de ZE régressé sur X) : β̂ suit alors la pente vraie, et le bruit ne
    // pilote plus que la dispersion, le R² et la t-stat — plus lisible pédagogiquement.
    var xs=[], i;
    for (i=0;i<n;i++){ xs.push(XMEAN + XSD*ZX[i]); }
    var mxx=0, mze=0; for (i=0;i<n;i++){ mxx+=xs[i]; mze+=ZE[i]; } mxx/=n; mze/=n;
    var sxx0=0, sxe0=0;
    for (i=0;i<n;i++){ var dx0=xs[i]-mxx; sxx0+=dx0*dx0; sxe0+=dx0*(ZE[i]-mze); }
    var g0 = sxx0>0 ? sxe0/sxx0 : 0;
    var ys=[];
    for (i=0;i<n;i++){
      var e = (ZE[i]-mze) - g0*(xs[i]-mxx);   // choc orthogonal à X
      ys.push(ALPHA + beta*xs[i] + noise*e);
    }
    // Moments
    var mx=0,my=0; for (i=0;i<n;i++){ mx+=xs[i]; my+=ys[i]; } mx/=n; my/=n;
    var Sxx=0,Syy=0,Sxy=0;
    for (i=0;i<n;i++){ var dx=xs[i]-mx, dy=ys[i]-my; Sxx+=dx*dx; Syy+=dy*dy; Sxy+=dx*dy; }
    var bhat = Sxx>0 ? Sxy/Sxx : 0;
    var ahat = my - bhat*mx;
    var RSS=0; for (i=0;i<n;i++){ var r=ys[i]-(ahat+bhat*xs[i]); RSS+=r*r; }
    var s2 = n>2 ? RSS/(n-2) : 0;
    var seB = (Sxx>0 && s2>0) ? Math.sqrt(s2/Sxx) : 0;
    var t = seB>0 ? bhat/seB : 0;
    var R2 = (Sxx>0 && Syy>0) ? (Sxy*Sxy)/(Sxx*Syy) : 0;

    setT("rg-bhat", bhat.toFixed(2)); setT("rg-r2", R2.toFixed(3)); setT("rg-t", t.toFixed(2));
    var reject = Math.abs(t) > 1.96;
    var dec = document.getElementById("rg-dec");
    var sig = al()==="en"?"Significant":(al()==="nl"?"Significant":"Significatif");
    var ns  = al()==="en"?"Not significant":(al()==="nl"?"Niet significant":"Non significatif");
    dec.textContent = reject ? sig : ns;
    dec.style.color = reject ? "var(--teal)" : "var(--crimson)";

    // Échelle du dessin
    var W=520,H=300,L=44,R=16,T0=16,B=34, pw=W-L-R, ph=H-T0-B;
    var xmin=Infinity,xmax=-Infinity,ymin=Infinity,ymax=-Infinity;
    for (i=0;i<n;i++){ if(xs[i]<xmin)xmin=xs[i]; if(xs[i]>xmax)xmax=xs[i]; if(ys[i]<ymin)ymin=ys[i]; if(ys[i]>ymax)ymax=ys[i]; }
    var xpad=(xmax-xmin)*0.08||1, ypad=(ymax-ymin)*0.08||1;
    xmin-=xpad; xmax+=xpad; ymin-=ypad; ymax+=ypad;
    function px(x){ return L + (x-xmin)/(xmax-xmin)*pw; }
    function py(y){ return T0 + (1-(y-ymin)/(ymax-ymin))*ph; }

    var g="";
    // axes
    g+='<line class="axis" x1="'+L+'" y1="'+(T0+ph)+'" x2="'+(L+pw)+'" y2="'+(T0+ph)+'"/>';
    g+='<line class="axis" x1="'+L+'" y1="'+T0+'" x2="'+L+'" y2="'+(T0+ph)+'"/>';
    // ligne y=0 si visible
    if (ymin<0 && ymax>0){ g+='<line x1="'+L+'" y1="'+py(0).toFixed(1)+'" x2="'+(L+pw)+'" y2="'+py(0).toFixed(1)+'" stroke="var(--ink-mute)" stroke-width="1" stroke-dasharray="2 4" opacity="0.5"/>'; }
    // droite OLS ajustée
    var x0=xmin, x1=xmax;
    g+='<line x1="'+px(x0).toFixed(1)+'" y1="'+py(ahat+bhat*x0).toFixed(1)+'" x2="'+px(x1).toFixed(1)+'" y2="'+py(ahat+bhat*x1).toFixed(1)+'" stroke="var(--ink)" stroke-width="2.4"/>';
    // nuage de points
    for (i=0;i<n;i++){ g+='<circle cx="'+px(xs[i]).toFixed(1)+'" cy="'+py(ys[i]).toFixed(1)+'" r="3.1" fill="var(--teal)" opacity="0.72"/>'; }
    // libellés d'axes
    var xlab = al()==="en"?"X — factor / market":(al()==="nl"?"X — factor / markt":"X — facteur / marché");
    var ylab = al()==="en"?"Y — asset return":(al()==="nl"?"Y — activarendement":"Y — rendement actif");
    g+='<text class="lab" x="'+(L+pw)+'" y="'+(T0+ph+16)+'" text-anchor="end">'+xlab+'</text>';
    g+='<text class="lab" x="'+L+'" y="'+(T0-4)+'" text-anchor="start">'+ylab+'</text>';
    svg.innerHTML=g;
  }
  ["rg-beta","rg-noise","rg-n"].forEach(function(id){ var e=document.getElementById(id); if(e) e.addEventListener("input", draw); });
  document.querySelectorAll("[data-set-lang]").forEach(function(b){ b.addEventListener("click", function(){ setTimeout(draw,10); }); });
  document.addEventListener("DOMContentLoaded", draw);
  draw();
})();
